-- Панель: вакансии в базе (раньше — константы на сайте), магазины / склады и тексты — в панели.
CREATE TABLE vacancies (
  id         serial PRIMARY KEY,
  slug       text NOT NULL UNIQUE,              -- якорь карточки на странице (#slug)
  dept       text NOT NULL DEFAULT '',          -- отдел / магазин
  title      text NOT NULL,
  city       text NOT NULL DEFAULT '',
  experience text NOT NULL DEFAULT '',
  schedule   text NOT NULL DEFAULT '',
  salary     text NOT NULL DEFAULT '',
  blocks     jsonb NOT NULL DEFAULT '[]'::jsonb, -- [{"title": "Обязанности", "items": ["…"]}]
  sort       int NOT NULL DEFAULT 0,
  is_active  boolean NOT NULL DEFAULT true,     -- false — скрыта с сайта
  created_at timestamptz NOT NULL DEFAULT now()
);

